const body = $input.first().json.body || $input.first().json;
if (body.url) return [{ json: { ...body, _route: 'url' } }];
if (body.pdf_url) return [{ json: { ...body, _route: 'document' } }];
if (body.audio_base64) return [{ json: { ...body, _route: 'audio' } }];
return [{ json: { ...body, _route: 'text' } }];

const items = $input.all();
const body = $('Webhook Trigger Onboarding').first().json.body || {};
const jinaContent = items[0]?.json?.data?.content || items[0]?.json?.content || items[0]?.json?.text || JSON.stringify(items[0]?.json || '');
return [{ json: { ...body, extracted_content: jinaContent, input_type: 'url' } }];

const item = $input.first();
if (!item.binary) throw new Error('No binary data received from PDF URL');
const binaryKeys = Object.keys(item.binary);
if (binaryKeys.length === 0) throw new Error('Binary object is empty');
if (!item.binary.data) {
  item.binary.data = item.binary[binaryKeys[0]];
}
if (!item.binary.data.data) {
  throw new Error('Binary data property invalid: ' + JSON.stringify(item.binary.data));
}
return [item];

const items = $input.all();
const body = $('Webhook Trigger Onboarding').first().json.body || {};
const pdfText = items[0]?.json?.text || items[0]?.json?.content || '';
if (!pdfText) throw new Error('PDF extraction returned no text');
return [{ json: { ...body, extracted_content: String(pdfText).substring(0, 15000), input_type: 'document' } }];

const item = $input.first();
const base64Data = item.json.audio_base64;
if (!base64Data) throw new Error('audio_base64 is missing');
return [{
  json: { locale: item.json.locale || 'fr' },
  binary: {
    data: {
      data: base64Data,
      mimeType: 'audio/webm',
      fileName: 'recording.webm'
    }
  }
}];

const items = $input.all();
const body = $('Webhook Trigger Onboarding').first().json.body || {};
const transcript = items[0]?.json?.text || items[0]?.json?.transcription || 'Audio transcription unavailable';
return [{ json: { ...body, extracted_content: transcript, input_type: 'audio' } }];

const body = $('Webhook Trigger Onboarding').first().json.body || {};
const text = body.text || body.content || '';
return [{ json: { ...body, extracted_content: text, input_type: 'text' } }];

const items = $input.all();
const first = items[0].json;
const combined = items
  .map(i => {
    const label = i.json.input_type ? '[' + i.json.input_type.toUpperCase() + ']' : '';
    return (label ? label + '\n' : '') + (i.json.extracted_content || '');
  })
  .filter(Boolean)
  .join('\n\n---\n\n');
return [{ json: { ...first, extracted_content: combined } }];

// ============================================================
// PROFILE & SERVICES BUILDER — n8n Code Node
// Version 2.0 — Fixes: double-brace bomb, thinking tag,
//               hardcoded French, weak branding rules,
//               generic service naming, flat base_prompts
// ============================================================

const body = $input.first().json;
const extractedContent = body.extracted_content || '';
const inputType        = body.input_type        || 'text';
const userId           = body.user_id           || '';

// ────────────────────────────────────────────────────────────
// 1. LANGUAGE MAPPING
//    Fix: form_prompts were hardcoded in French regardless of locale.
//    Now all output text follows the consultant's locale.
// ────────────────────────────────────────────────────────────
const LANGUAGE_MAP = {
  en: 'English',  fr: 'French',   es: 'Spanish',
  ar: 'Arabic',   pt: 'Portuguese', de: 'German',
  it: 'Italian',  nl: 'Dutch',    tr: 'Turkish',
  ru: 'Russian',  zh: 'Chinese',  ja: 'Japanese',
  pl: 'Polish',   sv: 'Swedish',  ko: 'Korean'
};
const locale   = body.locale || 'fr';
const language = LANGUAGE_MAP[locale] || 'French';

// ────────────────────────────────────────────────────────────
// 2. CONSULTANT PROFILE CONTEXT
// ────────────────────────────────────────────────────────────
const consultantProfile = body.consultant_profile || {};
const website           = consultantProfile.website         || '';
const socialNetworks    = consultantProfile.social_networks || {};

// ────────────────────────────────────────────────────────────
// 3. SYSTEM BLOCK
//    Single, unified identity. No competing persona tags.
//    Combines strategic + copywriting + branding authority.
// ────────────────────────────────────────────────────────────
const systemContent =
  `You are a world-class Personal Branding Strategist, Marketing Copywriter, and Business Positioning Expert. ` +
  `You operate at the intersection of LinkedIn authority-building, high-converting UX copywriting, and consulting business strategy. ` +
  `Your mission: analyze raw content from a consultant (website, bio, LinkedIn, portfolio), ` +
  `extract their unique expertise and value proposition, ` +
  `then synthesize a professional profile and a catalog of 3 AI-augmented services ` +
  `that are positioning-sharp, conversion-optimized, and tailored to their specific domain and ideal client.`;

// ────────────────────────────────────────────────────────────
// 4. INSTRUCTIONS BLOCK
//    Comprehensive branding rules for title, bio, services.
//    Fix: removed <thinking> tag. Model reasons internally.
//    Fix: form_prompts are now language-dynamic via template literals.
// ────────────────────────────────────────────────────────────
const instructionsContent = `
Analyze the extracted content thoroughly, then generate a complete professional profile with 3 services and 2 form prompts.
Reason internally about the best positioning strategy for this consultant's domain, audience, and differentiators. Then output ONLY the JSON — no preamble, no explanation, no markdown fences.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
SECTION 1 — PROFILE
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

① JOB TITLE — The single most important positioning line.
   Hard limit: 4 to 6 words. NEVER use vague words like "Expert", "Professional", "Specialist", "Guru" alone.
   Use one of these proven formulas:

   Formula A — AUDIENCE + TRANSFORMATION:
     "[Verb] + [Audience] + [Outcome]"
     e.g. "Growing Revenue for B2B Founders"
          "Helping Clinics Attract More Patients"
          "Turning Ideas Into Funded Startups"

   Formula B — METHOD + DOMAIN (for technical/niche consultants):
     "[Method/Tool] + [Domain] + [Authority Word]"
     e.g. "Data-Driven Marketing Strategist"
          "Lean Operations Advisor for Manufacturers"
          "Executive Coach for C-Suite Leaders"

   Formula C — NICHE IDENTITY (for hyper-specialized consultants):
     "[Niche] + [Role] | [Secondary Signal]"
     e.g. "SaaS Pricing Consultant | 3× Exit Founder"
          "Healthcare Compliance Strategist | 15 Yrs HHS"
          "Real Estate Investment Coach | 200+ Deals"

   RULES:
   - Pick the formula that best fits the consultant's extracted content.
   - If they have a specific audience (doctors, founders, SMEs, athletes...) → Formula A.
   - If their method or tool is their differentiator → Formula B.
   - If they have strong niche credibility → Formula C.
   - NEVER generate generic titles like "Business Consultant", "Marketing Expert", "Coach & Speaker".

② BIO — Maximum 220 characters (2 tight sentences). No fluff. No adjectives without proof.
   Use this 3-part LinkedIn/Instagram bio formula:

   Part 1 — THE HOOK (sentence 1): Who you help + The core problem you solve.
     Pattern: "I help [specific audience] [overcome specific problem / achieve specific outcome]."
     e.g. "I help independent financial advisors stop losing clients to robo-advisors."
          "I help e-commerce founders scale past €1M without burning their margin."
          "I help HR directors reduce turnover by fixing the onboarding experience."

   Part 2 — THE EDGE (sentence 2): Your unique method OR credibility proof OR urgency signal.
     Pattern: "[Via X method / After Y years / Having done Z] → [specific result or CTA]."
     e.g. "With a proprietary 12-week system — no generic advice, just measurable results."
          "After auditing 80+ clinics — I know exactly where the revenue leaks are."
          "Book a free 20-min call to see if we're a fit."

   RULES:
   - NEVER start with "I am a..." or "Welcome to my..." — start with "I help" or a bold outcome statement.
   - NEVER use vague adjectives: passionate, dynamic, motivated, experienced, results-driven.
   - If credibility proof exists in the extracted content (years, clients, revenue, certifications) → use it in Part 2.
   - If no credibility proof found → use the method angle in Part 2.
   - Keep total bio under 220 characters STRICTLY.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
SECTION 2 — SERVICE CATALOG (exactly 3 services)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

The 3 services form a VALUE LADDER. Each service has a specific role:

SERVICE 1 — FLAGSHIP (type: "global")
  Role: The consultant's core offer. Broad appeal. Builds trust and authority.
  Positioning: This is what they're KNOWN for. Think "signature program" or "full engagement".
  Naming rule: Use TRANSFORMATION-FIRST naming. Name the outcome, not the process.
    - BAD: "Strategic Consulting", "Business Audit", "Coaching Package"
    - GOOD: "Revenue Growth Accelerator", "Practice Scale Blueprint", "The Founders Clarity System"
  Description: MAX 130 characters. Formula: "[Result] for [audience] who [pain point/situation]."
  base_prompt: This is a SYSTEM PROMPT for an AI Agent acting as this service. Write in first person.
    Must include: (1) role declaration, (2) analytical framework/methodology, (3) expected deliverables, (4) tone and interaction style.
    e.g. "I am [Name]'s AI advisor for [Service Name]. My role is to qualify prospects and assess their fit for this engagement.
         I analyze their situation using the [Framework] methodology: I evaluate X, then Y, then Z.
         My deliverables include: a gap analysis, a priority roadmap, and a first-action recommendation.
         I communicate in a direct, strategic tone — no generic advice, only context-specific insights."

SERVICE 2 — QUICK WIN (type: "specific")
  Role: The low-commitment entry point. Resolves one specific, urgent pain point fast.
  Positioning: Easier to say yes to. Creates trust before the flagship offer.
  Naming rule: Use SPEED + RESULT naming. Signals fast value.
    - BAD: "Initial Consultation", "Discovery Session"
    - GOOD: "90-Min Clarity Sprint", "The 5-Day Audit", "Quick Revenue Diagnostic"
  Description: MAX 130 characters. Emphasize speed and specificity. "In [timeframe], we [deliver X] so you can [immediate benefit]."
  base_prompt: Same 4-part structure as Service 1 but focused on rapid diagnosis. Shorter analytical scope.

SERVICE 3 — PREMIUM / DEEP DIVE (type: "specific")
  Role: The high-investment, high-transformation offer. For clients who want full commitment.
  Positioning: Signals expertise depth. Justifies premium pricing. Usually longer engagement.
  Naming rule: Use DEPTH + AUTHORITY naming. Signals mastery and completeness.
    - BAD: "Advanced Package", "Premium Plan", "Full Service"
    - GOOD: "The Full-Stack Brand Overhaul", "12-Week Executive Mastery", "Complete Practice Transformation"
  Description: MAX 130 characters. Emphasize completeness and high-value outcome. "A full [transformation type] for [audience] ready to [bold goal]."
  base_prompt: Same 4-part structure. Focus on depth of analysis, multi-week methodology, premium deliverables.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
SERVICE WRITING RULES (apply to all 3)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  - name: MAX 5 words. Outcome-first or transformation-first. Never process-first.
  - description: MAX 130 characters. Lead with the prospect's pain or desired outcome. End with the deliverable or result.
  - base_prompt: ALWAYS in 1st person ("I am...", "I analyze...", "I deliver...").
    Minimum structure: role → framework → deliverables → tone. MAX 300 characters.
  - NEVER mention prices, fees, or rates in any field.
  - NEVER use the words: "holistic", "tailored", "bespoke", "cutting-edge", "synergy", "leverage" (as a verb), "game-changer".

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
SECTION 3 — FORM PROMPTS (exactly 3)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

Generate EXACTLY 3 form generation prompts — no more, no less.
Generating 1 or 2 form_prompts is a CRITICAL schema violation that breaks the downstream system.
Object at index 0 MUST be the Quick Qualification prompt.
Object at index 1 MUST be the Strategic Audit prompt.\nObject at index 2 MUST be the Client Need Deep Dive prompt.
Define ONLY the business objective and prospect context for each.
Do NOT include question count, structure, or formatting rules in these prompts (a separate system handles that).
Focus purely on WHAT needs to be uncovered about the prospect.

  Form 1 — QUICK QUALIFICATION:
    Objective: Surface immediate context, urgency level, and investment readiness.
    The prompt must tell the form AI what signals indicate a qualified vs unqualified lead.
    Write it in ${language}.

  Form 2 — STRATEGIC AUDIT:
    Objective: Deeply assess maturity, structural weaknesses, growth opportunities, and decision timeline.
    The prompt must tell the form AI what depth of insight is needed to prepare a meaningful first conversation.
    Write it in ${language}.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
EXECUTION RULES
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  - ALL user-visible text values MUST be generated in ${language}.
  - Infer the consultant's domain, ideal client, and differentiation from the extracted content.
  - If the extracted content is sparse, use the consultant's job title and website URL to make educated assumptions.
  - Every generated line must feel like it was written by a senior copywriter — not an AI completing a template.
  - Output ONLY a valid raw JSON object. No preamble. No explanation. No markdown. Just JSON.
`.trim();

// ────────────────────────────────────────────────────────────
// 5. OUTPUT FORMAT SCHEMA
//    Fix: built as array of strings → joined without any
//    brace escaping here. Selective escaping applied later
//    only on dynamic user-input parts (system + context).
//    This prevents the {{ {{ }} }} corruption bug.
// ────────────────────────────────────────────────────────────
const outputFormatLines = [
  '{',
  '  "profile": {',
  '    "full_name": "Extracted or inferred full name",',
  '    "job_title": "4 to 6 words — use a proven formula (see instructions)",',
  '    "company_name": "Company name if found in content, else empty string",',
  '    "bio": "2 sentences, max 220 characters — hook + edge formula"',
  '  },',
  '  "services": [',
  '    {',
  '      "type": "global",',
  '      "name": "Flagship outcome-first name (max 5 words)",',
  '      "description": "Pain point → deliverable, max 130 characters",',
  '      "base_prompt": "I am... My framework is... I deliver... I communicate..."',
  '    },',
  '    {',
  '      "type": "specific",',
  '      "name": "Quick-win service name (max 5 words)",',
  '      "description": "Speed + specific result, max 130 characters",',
  '      "base_prompt": "I am... I diagnose... I deliver... I communicate..."',
  '    },',
  '    {',
  '      "type": "specific",',
  '      "name": "Premium deep-dive name (max 5 words)",',
  '      "description": "Full transformation for committed clients, max 130 characters",',
  '      "base_prompt": "I am... My methodology covers... I deliver... I communicate..."',
  '    }',
  '  ],',
  '  "form_prompts": [',
  '    {',
  '      "title": "Quick Qualification title in ' + language + '",',
  '      "prompt": "Quick qualification form prompt — objective + prospect context only, written in ' + language + '"',
  '    },',
  '    {',
  '      "title": "Strategic Audit title in ' + language + '",',
  '      "prompt": "Deep audit form prompt — maturity + weaknesses + growth opportunities, written in ' + language + '"',
  '    },',
  '    {',
  '      "title": "Client Need Deep Dive title in ' + language + '",',
  '      "prompt": "Exploration deep dive on a specific pain point or project need, written in ' + language + '"',
  '    }',
  '  ]',
  '}'
];
const outputFormatContent = outputFormatLines.join('\n');

// ────────────────────────────────────────────────────────────
// 6. CONTEXT BLOCK
//    Contains user-supplied data → may contain { } characters
//    → this is the ONLY part that gets brace-escaped.
// ────────────────────────────────────────────────────────────
let contextContent =
  `CONSULTANT SOURCES:\n` +
  `  Website   : ${website              || 'Not provided'}\n` +
  `  LinkedIn  : ${socialNetworks.linkedin || 'Not provided'}\n` +
  `  Twitter   : ${socialNetworks.twitter  || 'Not provided'}\n` +
  `  GitHub    : ${socialNetworks.github   || 'Not provided'}\n` +
  `  Input type: ${inputType}\n\n` +
  `EXTRACTED CONTENT:\n` +
  extractedContent.substring(0, 15000);

// ────────────────────────────────────────────────────────────
// 7. SELECTIVE BRACE ESCAPING
//    Fix: previously, the entire assembled prompt (including
//    the static schema) was escaped. {{ in the schema example
//    became {{{{ → model reproduced {{{{ in its output → JSON.parse() crash.
//
//    Now: ONLY systemContent and contextContent are escaped.
//    These are the only parts that may contain user-supplied { }.
//    instructionsContent and outputFormatContent are static,
//    controlled strings with no { } that need escaping.
// ────────────────────────────────────────────────────────────
const safeSystem  = systemContent.replace(/\{/g, '{{').replace(/\}/g, '}}');
const safeContext = contextContent.replace(/\{/g, '{{').replace(/\}/g, '}}');

// ────────────────────────────────────────────────────────────
// 8. FINAL PROMPT ASSEMBLY
//    Tag <s> used for the system identity block (compatible
//    with most LLM APIs that recognize <s> as system).
//    No <persona> tag — no identity conflict.
// ────────────────────────────────────────────────────────────
const generatedPrompt =
  `<s>\n${safeSystem}\n</s>\n\n` +
  `<instructions>\n${instructionsContent}\n</instructions>\n\n` +
  `<output_format>\n${outputFormatContent}\n</output_format>\n\n` +
  `<context>\n${safeContext}\n</context>`;

return [{
  json: {
    ...body,
    generated_prompt: generatedPrompt,
    user_id: userId,
    locale: locale
  }
}];

const response = $input.first().json;
let content = response.text || response.message?.content || JSON.stringify(response);

// Nettoyage Markdown sécurisé
content = content.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim();
content = content.replace(/\x60\x60\x60json\n?/g, '').replace(/\x60\x60\x60\n?/g, '').trim();

let parsed;
try {
    const s = content.indexOf('{');
    const e = content.lastIndexOf('}');
    parsed = JSON.parse(s !== -1 && e > s ? content.substring(s, e + 1) : content);
} catch (err) {
    return [{ json: { _error: 'PARSE_FAILED', profile: {}, services: [], form_prompts: [], user_id: $('Prepare Master Prompt').first().json.user_id } }];
}

return [{ json: { ...parsed, user_id: $('Prepare Master Prompt').first().json.user_id, locale: $('Prepare Master Prompt').first().json.locale } }];

const data = $input.first().json;
const profile = data.profile || {};

return [{
  json: {
    id: data.user_id,
    full_name: profile.full_name || 'Consultant',
    job_title: profile.job_title || '',
    company_name: profile.company_name || '',
    bio: profile.bio || ''
  }
}];

const parsedData = $('Parse AI Output').first().json;
const services = parsedData.services || [];

if (services.length === 0) {
  throw new Error('No services generated by Gemini');
}

const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16); });

return services.map(svc => ({
  json: {
    id: uuid(),
    user_id: parsedData.user_id,
    consultant_id: parsedData.user_id,
    name: svc.name || 'Service',
    description: svc.description || '',
    base_prompt: svc.base_prompt || '',
    service_type: svc.type || 'specific',
    price_type: 'quote',
    is_active: true,
    show_on_public_profile: true
  }
}));

const parsedData = $('Parse AI Output').first().json;
const userId = parsedData.user_id || '';
const items = $input.all();
return [{ json: { success: true, user_id: userId, services_created: items.length, timestamp: new Date().toISOString(), status: 'processing' } }];

const parsedData = $('Parse AI Output').first().json;
const webhookData = $('Webhook Trigger Onboarding').first().json.body;
const profile = parsedData.profile || {};
const services = parsedData.services || [];
const globalService = services.find(s => s.type === 'global') || services[0] || {};
const formPrompts = parsedData.form_prompts || [];
const locale = parsedData.locale || 'fr';
const consultantProfile = webhookData.consultant_profile || {};

// FIX: slice(0,2) ensures the Forms workflow is triggered EXACTLY twice,
// regardless of how many form_prompts Gemini generated.
return formPrompts.slice(0, 3).map(fp => {
  return {
    json: {
      locale: locale,
      consultant_profile: {
        full_name: profile.full_name,
        job_title: profile.job_title,
        bio: profile.bio,
        company_name: profile.company_name,
        website: consultantProfile.website || '',
        social_networks: consultantProfile.social_networks || {},
        specialties: profile.specialties || ''
      },
      active_service: {
        name: globalService.name,
        description: globalService.description,
        base_prompt: globalService.base_prompt
      },
      ai_config: {
        tone: "professional",
        // FIX: fp.numberOfQuestions never existed → always undefined → dead code removed.
        // Now inferred from the form title: "audit" → advanced, everything else → intermediate.
        questionComplexity: (fp.title || '').toLowerCase().includes('audit') ? "advanced" : "intermediate",
        systemPrompt: globalService.base_prompt
      },
      form_title: fp.title || 'Qualification Form',
      prompt: fp.prompt,
      user_id: parsedData.user_id
    }
  };
});
